quests[36566] = { id = 36566, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steinbrecherarena" }
quests[36567] = { id = 36567, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Größer heißt besser", description = "Wisst Ihr was, <Scheff/Scheffin>, ich glaube, ich weiß, wie wir diesen Ort weiter ausbauen können. Größere Mauern. Mehr Gebäude. Etwas Platz, um nach einem Tag voller Abenteuer den Rücken zu strecken.\n\nVersteht mich nicht falsch, es wird eine Menge Ressourcen verschlingen, aber wozu sonst sind all die Dinge da?\n\nWir können am Zeichentisch mit den Planungen beginnen, wann immer es Euch beliebt. Es wird bestimmt PRACHTVOLL!", sourceObjective = "Benutzt den Architektentisch, um Eure Große Halle auszuwählen und Eure Garnison auf Stufe 2 aufzuwerten.", completion = "Genau DAS hab ich gemeint! Seht Euch diesen Ort an!\n\nDort hinten haben wir sogar einen Teich. Bisschen kühl, sicher, aber man kann ja nich' immer 'n Tropenparadies verlangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[36568] = { id = 36568, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Malgosh Shadowkeeper" }
