quests[36571] = { id = 36571, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Iyunwald" }
quests[36573] = { id = 36573, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Eisen schlagen, solange es heiß ist", description = "Mit dem Herz des Magnaron haben wir eine mächtige Waffe gegen die Eiserne Horde.\n\nSie sammelt sich hoch im Norden beim Eisernen Vorstoß. Es wird kein leichtes Unterfangen, aber wir müssen die Gelegenheit beim Schopf packen, der Eisernen Horde einen Schlag zu verpassen, solange wir dieses Artefakt besitzen.\n\nWir können auf Euren Befehl hin aufbrechen. Sprecht mit Fratzenschlitzer, wenn Ihr bereit seid.", sourceObjective = "Sprecht mit Fratzenschlitzer, um zum Eisernen Vorstoß zu fliegen und die Eiserne Horde anzugreifen.", completion = "{name}, wir haben den Streitkräften der Eisernen Horde einen schweren Schlag zugefügt.", sourceObjectiveStatus = "unverified-source-field" }
quests[36574] = { id = 36574, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Eisen schlagen, solange es heiß ist", description = "Mit dem Willen der Genesaurier haben wir eine mächtige Waffe gegen die Eiserne Horde.\n\nUnsere Späher haben eine Basis der Eisernen Horde entdeckt, und wir sollten diese Gelegenheit beim Schopf packen.\n\nIhre Truppen sammeln sich hoch im Norden beim Eisernen Vorstoß. Es wird kein leichtes Unterfangen, aber wir müssen der Eisernen Horde einen Schlag verpassen, solange wir dieses Artefakt besitzen.\n\nWir können auf Euren Befehl hin aufbrechen. Sprecht mit Fratzenschlitzer, wenn Ihr bereit seid.", sourceObjective = "Sprecht mit Fratzenschlitzer, um zum Eisernen Vorstoß zu fliegen und die Eiserne Horde anzugreifen.", completion = "{name}, wir haben den Streitkräften der Eisernen Horde einen schweren Schlag zugefügt.", sourceObjectiveStatus = "unverified-source-field" }
quests[36575] = { id = 36575, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Eisen schlagen, solange es heiß ist", description = "Mit dem Willen der Genesaurier haben wir eine mächtige Waffe gegen die Eiserne Horde.\n\nUnsere Späher haben eine Basis der Eisernen Horde entdeckt, und wir sollten diese Gelegenheit beim Schopf packen.\n\nIhre Truppen sammeln sich hoch im Norden beim Eisernen Vorstoß. Es wird kein leichtes Unterfangen, aber wir müssen der Eisernen Horde einen Schlag verpassen, solange wir dieses Artefakt besitzen.\n\nWir können auf Euren Befehl hin aufbrechen. Sprecht mit Rangari Rajess, wenn Ihr bereit seid.", sourceObjective = "Sprecht mit Rangari Rajess, um zum Eisernen Vorstoß zu fliegen und die Eiserne Horde anzugreifen.", completion = "Kommandant, wir haben der Eisernen Horde einen schweren Schlag zugefügt. Wir werden sie besiegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[36576] = { id = 36576, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Eisen schlagen, solange es heiß ist", description = "Mit dem Herz des Magnarons haben wir eine mächtige Waffe gegen die Eiserne Horde.\n\nSie sammelt sich hoch im Norden beim Eisernen Vorstoß. Es wird kein leichtes Unterfangen, aber wir müssen die Gelegenheit beim Schopf packen, der Eisernen Horde einen Schlag zu verpassen, solange wir dieses Artefakt besitzen.\n\nWir können auf Euren Befehl hin aufbrechen. Sprecht mit Rangari Rajess, wenn Ihr bereit seid.", sourceObjective = "Sprecht mit Rangari Rajess, um zum Eisernen Vorstoß zu fliegen und die Eiserne Horde anzugreifen.", completion = "Kommandant, wir haben der Eisernen Horde einen schweren Schlag zugefügt. Wir werden sie besiegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[36577] = { id = 36577, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flugmaschine abgeschlossen" }
quests[36587] = { id = 36587, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Zwielichttor aufspüren" }
quests[36588] = { id = 36588, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking - See Closed Chest" }
quests[36589] = { id = 36589, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwere Waffen", description = "Es ist die ausgebrannte Hülle einer Art Massenvernichtungswaffe. Es könnte sich lohnen, in Eurer Garnison herumzufragen, ob jemand Euch dabei helfen kann, sie wieder funktionstüchtig zu machen.", sourceObjective = "Sucht in Eurer Garnison nach jemandem, der Euch bei der Reparatur helfen kann.", progress = "He, Scheff, was gibt's für mich zu tun?", completion = "Ich glaube, diese Schönheit könnte uns eine Menge Ärger einbringen!", sourceObjectiveStatus = "unverified-source-field" }
quests[36590] = { id = 36590, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Heulende Fels" }
quests[36592] = { id = 36592, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Größer heißt besser", description = "Kommandant, ich arbeite gerade an Plänen, die Euch vielleicht interessieren werden.\n\nWas haltet Ihr davon, die Mauern weiter nach außen zu versetzen, um Platz für weitere Gebäude zu erhalten? Unsere Truppenstärke ist gestiegen, und langsam wird es etwas eng hier. Deshalb würde ich diese zusätzlichen Baupläne gerne in die Tat umsetzen.\n\nWerft bitte einen Blick auf die Pläne hier auf dem Tisch, wenn Ihr Zeit habt. Sobald ich von Euch grünes Licht bekomme, werde ich sofort alle Mann an die Arbeit schicken.", sourceObjective = "Benutzt den Architektentisch, um Euer Rathaus auszuwählen und Eure Garnison auf Stufe 2 aufzuwerten.", completion = "VIEL besser! Jetzt rennt man nicht mehr dauernd in Mauern.\n\nDer Platz sollte für ein oder zwei weitere Gebäude reichen. Die Bauarbeiten können beginnen, sobald Ihr bereit seid. Ihr müsst mir nur zeigen, welcher Plan hier auf dem Tisch Euch interessiert.", sourceObjectiveStatus = "unverified-source-field" }
quests[36594] = { id = 36594, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "\"Überschüssige\" Teile", description = "So etwas habe ich noch nie zuvor gesehen! Aber alles kein Problem, <Scheff/Scheffin>. Wenn man damit Dinge in die Luft jagen kann, krieg ich's auch wieder zum Laufen.\n\nWir werden auf jeden Fall ein paar Teile brauchen – irgendeine Art von Munition könnte auch nicht schaden.\n\nHört sich an, als würden sich die Jungs von der Eisernen Horde mit Knallkörpern ganz gut auskennen.\n\nNehmt diese Werkzeuge und lasst uns mal sehen, ob wir nicht ein paar Ersatzteile requirieren können!", sourceObjective = "Sammelt 20 Schwarzeisengranaten und 50 Belagerungskanonenteile.", progress = "Das Zeug schon bekommen, Boss?", completion = "Was haltet Ihr von meiner schnellen Demontagetechnik? Ziemlich effektiv, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[36595] = { id = 36595, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Er hat sich Aggro...kultur aufgehalst.", description = "Was Ihr gesehen habt, war das Erwachen des Genesauriers Iyu. Er hat dieses mechanische Monstrum und die Person, die es steuerte, gejagt.\n\nIch glaube, der Pilot dieses Gefährts ist noch am Leben und irgendwo in den Ruinen des Lagers gefangen.\n\nWenn Ihr ihn findet wollt, dann wäre jetzt die richtige Zeit dafür.", sourceObjective = "Findet den Fahrer des Dunkeleisenpanzers.", completion = "Ah, perfekt. Die Karre läuft wieder, ehe Ihr Euch verseht.", sourceObjectiveStatus = "unverified-source-field" }
quests[36596] = { id = 36596, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Iron Horde Weapon Stash" }
quests[36597] = { id = 36597, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Berthora" }
quests[36600] = { id = 36600, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Riptar" }
quests[36601] = { id = 36601, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neuigkeiten aus Nagrand", description = "Einer unserer Soldaten hat nach Euch gefragt, als Ihr fort wart. Es ging um eine Karawane, die nach Nagrand aufgebrochen sein soll.\n\nWas auch immer passiert ist, es kann kein gutes Ende genommen haben. Das ist das Gebiet des Kriegshymnenklans.", sourceObjective = "Sprecht mit Bodrick Grau in Eurer Garnison im Schattenmondtal.", completion = "Kommandant. Schön, dass Ihr zurück seid.\n\nEs tut sich etwas in Nagrand. Die Einzelheiten findet Ihr hier am Aushang.", sourceObjectiveStatus = "unverified-source-field" }
quests[36602] = { id = 36602, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neuigkeiten aus Nagrand", description = "Einer unserer Soldaten hat nach Euch gefragt, als Ihr fort wart. Es ging um eine Karawane, die nach Nagrand aufgebrochen sein soll.\n\nWas auch immer passiert ist, es kann kein gutes Ende genommen haben. Das ist das Gebiet des Kriegshymnenklans.", sourceObjective = "Sprecht mit Rokhan in Eurer Garnison im Frostfeuergrat.", completion = "He, Scheff. Schön, dass Ihr zurück seid.\n\nIn Nagrand geht's rund. Einzelheiten findet Ihr hier am Aushang.", sourceObjectiveStatus = "unverified-source-field" }
quests[36603] = { id = 36603, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwefelquellen" }
quests[36604] = { id = 36604, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Dark Iron Emergency Pack" }
quests[36605] = { id = 36605, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Dark Iron Remains" }
quests[36606] = { id = 36606, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neuigkeiten aus Nagrand", description = "Willkommen zurück, Kommandant.\n\nEiner von Bodricks Männern hat eine Nachricht über eine Karawane überbracht, die nach Nagrand aufbrechen soll. Er wartet darauf, dass Ihr einen neuen Außenposten bewilligt.\n\nIch habe im Lager Gerüchte über Nagrand gehört. Es soll das Territorium des Kriegshymnenklans sein. Vielleicht brauchen sie ja Eure Hilfe, Kommandant.", sourceObjective = "Sprecht mit Bodrick Grau in Eurer Garnison im Schattenmondtal.", completion = "Kommandant. Schön, dass Ihr zurück seid.\n\nEs tut sich etwas in Nagrand. Die Einzelheiten findet Ihr hier am Aushang.", sourceObjectiveStatus = "unverified-source-field" }
quests[36607] = { id = 36607, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neuigkeiten aus Nagrand", description = "Willkommen zurück, Kommandant.\n\nEiner unserer Schattenjäger hat eine Nachricht über eine Karawane überbracht, die nach Nagrand aufbrechen soll. Rokhan wartet darauf, dass Ihr einen neuen Außenposten bewilligt.\n\nIch habe im Lager Gerüchte über Nagrand gehört. Es soll das Territorium des Kriegshymnenklans sein. Vielleicht brauchen sie ja Eure Hilfe, Kommandant.", sourceObjective = "Sprecht mit Rokhan in Eurer Garnison im Frostfeuergrat.", completion = "He, Scheff. Schön, dass Ihr zurück seid.\n\nIn Nagrand geht's rund. Einzelheiten findet Ihr hier am Aushang.", sourceObjectiveStatus = "unverified-source-field" }
quests[36608] = { id = 36608, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche nach Nat Pagle", description = "Jetzt, da Ihr den Beweis habt, könnten wir versuchen, Nat Pagle zu überreden, sich uns hier draußen anzuschließen.\n\nAls ich zuletzt von ihm hörte, hieß es, dass er drüben in Pandaria mit der dortigen Anglerfraktion am Fischen ist. Irgendwo vor der Küste der Krasarangwildnis. Reist dort hin, zeigt ihm Euren Fang und versucht, ihn mit hierher zu bringen!", sourceObjective = "Reist zur Anlegestelle der Angler in der Krasarangwildnis und sprecht mit Nat Pagle.", completion = "Ihr kommt aus Draenor? Wie soll das überhaupt funktionieren?!", sourceObjectiveStatus = "unverified-source-field" }
quests[36609] = { id = 36609, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der große Angler kehrt zurück", description = "Was ist das für eine Spezies? Ein Schmelzwels, sagt Ihr? Von solch einem Fisch habe ich noch nie gehört, geschweige denn, selbst einen zu Gesicht bekommen!\n\nIch muss mehr von diesen Fischen sehen, denn genau für so etwas lebe ich schließlich! Und wenn das Angeln dort so gut ist, wie Ihr sagt, dann werde ich mir diese Gelegenheit auf keinen Fall entgehen lassen. Nehmt diese Seite aus meinem Tagebuch als Beweis, dass Ihr mich gefunden habt. Wir treffen uns dann in Eurer Garnison.", sourceObjective = "Kehrt zu Rak'jin zurück und zeigt Nats Tagebuchseite als Beweis, dass Ihr ihn gefunden habt.", progress = "Ihr habt Nat gefunden? Den echten Nat Pagle?!", completion = "Wir werden sicher ein paar Riesenfische fangen, wenn Nat erst mal hier ist!", sourceObjectiveStatus = "unverified-source-field" }
quests[36610] = { id = 36610, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Gorge Spear" }
quests[36611] = { id = 36611, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein wahrer Angler von Draenor", description = "Wenn Ihr möchtet, dass ich Euch hier dauerhaft helfe, müsst Ihr mir zuerst ein paar dieser riesigen Draenorfänge zeigen. Geht raus in die Wildnis und bringt mir den größten Fisch aus der ganzen Gegend.\n\nIch habe diesen besonderen Köder für Euch gefertigt. Er hat mich noch nie im Stich gelassen. Bitte geht vorsichtig damit um!", sourceObjective = "Fangt in jeder Zone in Draenor einen Oschi und bringt sie zu Nat Pagle.", progress = "Was habt Ihr gefangen?", completion = "Diese Fische sind vorzüglich, {name}. Gute Arbeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[36612] = { id = 36612, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Köder für Nat", description = "Ihr habt jetzt genug Erfahrung mit dem Angeln in Draenor gewonnen, sodass wir nun versuchen können, Nat Pagle zu überreden, sich uns hier anzuschließen.\n\nWenn wir Nat wirklich überzeugen wollen, dann müssen wir ihm einen echten Beweis für die unglaublichen Fangmöglichkeiten hier in Draenor präsentieren. Geht zu den Lavaseen hier im Frostfeuergrat und versucht es dort. Die Perfektionierung Eurer Fähigkeiten in Draenor muss sich jetzt bezahlt machen.", sourceObjective = "Fangt einen Schmelzwels im Frostfeuergrat und bringt ihn zu Rak'jin.", progress = "Hattet Ihr Glück bei diesen Lavateichen?", completion = "Der ist perfekt... So einen Fisch kann niemand einfach abtun, erst recht nicht jemand wie Nat!", sourceObjectiveStatus = "unverified-source-field" }
quests[36614] = { id = 36614, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meine ganz eigene Festung", description = "Boss! Das glaubt Ihr nicht! Ich habe endlich das neue große Zeichenpapier geliefert bekommen, das ich bei unserer Ankunft hier bestellt hatte. Und wisst Ihr, was größeres Zeichenpapier bedeutet?\n\nEs bedeutet, dass ich eine größere Garnison zeichnen kann!\n\nUnd was ich zeichnen kann, können wir bestimmt auch bauen! Bauen ist der einfachere Teil, na ja, jedenfalls wenn wir ein paar tausend Steine und Baumstämme rumliegen hätten.\n\nAlso, <Scheff/Scheffin>, was sagt Ihr? Fangen wir an zu bauen?", sourceObjective = "Sammelt 2000 Garnisonsressourcen und benutzt dann den Architektentisch, um Eure Große Halle auszuwählen und Eure Garnison auf Stufe 3 aufzuwerten.", completion = "Ich glaube, würde ich jetzt tot umfallen, würde ich glücklich sterben. Ein Traum ist wahr geworden!\n\nIch habe auch schon noch größeres Zeichenpapier bestellt, Boss. Also nur keine Sorge...", sourceObjectiveStatus = "unverified-source-field" }
quests[36615] = { id = 36615, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meine ganz eigene Garnison", description = "Kommandant! Gute Neuigkeiten! Ich habe endlich das neue große Zeichenpapier geliefert bekommen, das ich bei unserer Ankunft hier bestellt hatte. Und wisst Ihr, was größeres Zeichenpapier bedeutet?\n\nEs bedeutet, dass ich eine größere Garnison zeichnen kann!\n\nUnd was ich zeichnen kann, können wir bestimmt auch bauen! Bauen ist der einfachere Teil, na ja, jedenfalls wenn wir ein paar tausend Steine und Baumstämme rumliegen hätten.\n\nAlso, <mein Herr/meine Dame>, was sagt Ihr? Fangen wir an zu bauen?", sourceObjective = "Sammelt 2000 Garnisonsressourcen und benutzt den Architektentisch, um Euer Rathaus auszuwählen und Eure Garnison auf Stufe 3 aufzuwerten.", completion = "Ich... Ich denke, das gefällt mir. Ein wenig mehr blaue Farbe und vielleicht noch ein paar größere Türme, aber man kann es wirklich schon Zuhause nennen, meint Ihr nicht?\n\nIch habe auch schon noch größeres Zeichenpapier bestellt, Kommandant. Also nur keine Sorge...", sourceObjectiveStatus = "unverified-source-field" }
quests[36616] = { id = 36616, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Angler in unserem Team", description = "Ihr seid wahrlich <ein Meisterangler/eine Meisteranglerin>!\n\nIch freue mich darauf, mich Euch hier in Draenor anschließen zu können und Euch zu helfen, so viele Oschis wie möglich zu fangen. Aber lasst uns zuerst darauf anstoßen.", sourceObjective = "Sprecht mit Nat Pagle und bittet ihn, sich unserer Sache anzuschließen.", completion = "Ihr seid wahrlich ein Meisterangler!\n\nIch freue mich darauf, mich Euch hier in Draenor anschließen zu können und Euch zu helfen, so viele Oschis wie möglich zu fangen. Aber lasst uns zuerst darauf anstoßen.", sourceObjectiveStatus = "unverified-source-field" }
quests[36617] = { id = 36617, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Winterhauchgeschenk" }
quests[36618] = { id = 36618, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Iron Supply Chest" }
quests[36619] = { id = 36619, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sägewerk" }
quests[36621] = { id = 36621, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Gnome Canister" }
quests[36623] = { id = 36623, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogerinvasion!", description = "Kommandant, unsere Späher melden, dass Ogerbanden durch den Schnee marschieren. Wenn sie nach der Abreibung, die wir ihnen bereits verpasst haben, weiterkämpfen wollen, tue ich ihnen den Gefallen gern.", sourceObjective = "Schlagt die Invasion Eurer Garnison durch die Oger zurück.\n\n(Sprecht erneut mit Unteroffizier Grimmkinn, um zu beginnen.)", progress = "Wir müssen die Stellung halten!", completion = "Gegen größenmäßig überlegene Gegner zu kämpfen, ist eine feine Sache. Seid Ihr mit dem Verhalten Eurer Soldaten zufrieden, Kommandant?", sourceObjectiveStatus = "unverified-source-field" }
quests[36624] = { id = 36624, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auftritt in Ashran", description = "Unsere Basis in Ashran ist fast fertig, Kommandant.\n\nIhr würdet ein bedeutendes Zeichen Eurer Unterstützung setzen, wenn Ihr dorthin reist und Eure Genehmigung für den geplanten Grundriss des Stützpunktes persönlich überbringt.\n\nIch kann einen Flug für Euch in die Wege leiten, wenn Ihr möchtet.", sourceObjective = "Sprecht mit dem Gefreiten Tristan am Sturmschild in Ashran.", completion = "Jetzt wartet doch mal, Kumpel. Seht Ihr nicht, dass ich beschäftigt bin?\n\nKommandant! Ich wusste nicht, dass Ihr wirklich herkommen... Ich meine... Willkommen, Kommandant.", sourceObjectiveStatus = "unverified-source-field" }
quests[36625] = { id = 36625, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Discarded Pack" }
quests[36626] = { id = 36626, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gastgeber Howell", description = "Leutnant Howell sagte, dass Ihr vielleicht vorbeikommt.\n\nEs ist eine große Ehre, Euch persönlich kennenzulernen. Der Leutnant befindet sich im Gasthaus, ich bringe Euch dorthin.", sourceObjective = "Sprecht mit Leutnant Howell.", completion = "Kommandant {name}, ich bin so froh, dass Ihr es einrichten konntet. Es ist mir wirklich eine Ehre.", sourceObjectiveStatus = "unverified-source-field" }
quests[36627] = { id = 36627, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Dicke Frostfeuer-Berta", description = "Eine meiner besten Arbeiten, {name}! Mama wäre jetzt so stolz auf mich... wäre sie noch in einem Stück.\n\nWir müssen das Teufelsgerät erst einmal testen, bevor Ihr damit planlos in der Gegend herumlauft.\n\nIch hörte, dass es da draußen einige Grollhufe geben soll, die herumrandalieren.", sourceObjective = "Bringt 6 Grollhufe unter Kontrolle.", completion = "Hm... Klingt so, als ob sie immer noch etwas mehr Wumms bräuchte. Lasst mich noch einmal daran arbeiten, Boss. Ich seh mal, was ich da machen kann!\n\nImmerhin versteh ich jetzt die Technologie der Eisernen Horde viel besser. Ich habe eine Kopie meiner Notizen für Euch gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[36628] = { id = 36628, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Hammer of Glory" }
quests[36629] = { id = 36629, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inspiration für Ashran", description = "Ich hoffe, dass unsere Anlagen Euren hohen Ansprüchen genügen.\n\nDieses Gasthaus wird von Jaesia Rosenfreud geleitet, und meiner Meinung nach ist es der beste Ruheplatz auf ganz Draenor.\n\nTäglich kommen neue Rekruten durch das Portal. Unser neuester Rekrut, Nuhb Grünohr, ist gerade heute durch das Portal gekommen.\n\nWenn Ihr handeln wollt, um Waffen oder Rüstung zu erwerben, wird Verteidiger Nuurem Euch sicher gerne weiterhelfen.", sourceObjective = "Sprecht mit Jaesia Rosenfreud, Verteidiger Nuurem und Nuhb Grünohr.", progress = "Wie war Euer Spaziergang?", completion = "Ich danke Euch nochmals, dass Ihr die Zeit für einen Besuch erübrigen konntet, Kommandant. Ihr wisst ja nicht, wie viel uns das bedeutet.", sourceObjectiveStatus = "unverified-source-field" }
quests[36630] = { id = 36630, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein mürrischer Zwerg", description = "Bevor Ihr geht... Da ist jemand, mit dem Ihr vielleicht reden solltet.\n\nEr ist eigensinnig, ein wenig schroff und ziemlich anmaßend, aber er ist der beste Krieger, den ich seit Langem getroffen habe.\n\nAn der Front sollte er an Eurer Seite stehen, Kommandant. Und glaubt mir, dessen ist er sich bewusst.", sourceObjective = "Sprecht mit Delvar Eisenfaust.", completion = "Also, ich hab' jetzt wirklich keine Zeit für... Oh... Ihr seid es!", sourceObjectiveStatus = "unverified-source-field" }
quests[36631] = { id = 36631, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Sasha's Stash" }
quests[36632] = { id = 36632, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geheimnisse von Gorgrond", description = "Kommandant, man hat mich entsandt, um Euch abzufangen.\n\nYrel und Maraad sind am Wildwuchsbett gelandet, der Operationsbasis der Rangari in dem Gebiet.\n\nEure Anwesenheit wird umgehend erbeten.\n\nWir haben eine kleine Gruppe Feenschwingen östlich von hier stationiert. Wenn Ihr mit dem Flugmeister sprecht, wird er Euch bestimmt sicher dorthin bringen lassen.", sourceObjective = "Sucht Yrel am Wildwuchsbett in Gorgrond auf. Sprecht mit dem Greifenmeister Eurer Garnison oder dem Flugmeister auf der Bastionsklippe, um dorthin zu fliegen.", completion = "Willkommen in Gorgrond, Kommandant. Wir sind selbst gerade erst angekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[36633] = { id = 36633, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delvar Eisenfaust", sourceObjective = "Nun, es wurde aber auch Zeit, dass Ihr Euer Gesicht zeigt. Ich habe genug davon, mit diesen neuen Rekruten herumzuhängen.\n\nMeine Klinge ist scharf, meine Rüstung glänzt und sogar meinen Bart hab' ich heut' Morgen gekämmt!\n\nIch bin schon kampfbereit seit mein Großvater Gygax mir die erste Axt in das Patschehändchen gelegt hat.\n\nAlso, was sagt Ihr, Kommandant?", sourceObjectiveStatus = "unverified-source-field" }
quests[36634] = { id = 36634, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Sniper's Crossbow" }
quests[36635] = { id = 36635, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Euer erster Arbeitsauftrag", description = "Jetzt, da Ihr über ein Handwerksgebäude verfügt, können wir Aufträge für Euch erledigen. Kommt zu mir, um mit der ersten Charge zu beginnen, wenn Ihr die von uns benötigten Zutaten zusammengetragen habt.", sourceObjective = "Übergebt dem Gehilfen die Reagenzien, um Euren ersten Arbeitsauftrag des Berufsgebäudes zu beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[36636] = { id = 36636, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bauplan lesen" }
quests[36640] = { id = 36640, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anhänger erhalten" }
quests[36641] = { id = 36641, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Euer erster Arbeitsauftrag für Alchemie", description = "Jetzt, da Ihr über ein Alchemielabor verfügt, können wir alchemistische Katalysatoren für Euch fertigen. Sprecht mit meinem Mann, wenn Ihr die Bestandteile zusammengetragen habt, damit wir mit dem ersten Arbeitsauftrag beginnen können.", sourceObjective = "Beginnt Euren ersten Abeitsauftrag für Alchemie beim Alchemielabor und holt ihn anschließend ab.", progress = "Ja?", completion = "Lasst mich das für Euch auspacken.\n\nWir haben diesen Auftrag zwar schneller bearbeitet, aber Ihr solltet wissen, dass zukünftige Arbeitsaufträge zur Fertigstellung länger benötigen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[36642] = { id = 36642, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Euer erster Arbeitsauftrag für Lederverarbeitung", description = "Jetzt, da Ihr über eine Gerberei verfügt, können wir poliertes Leder für Euch fertigen. Sprecht mit meiner Gehilfin, wenn Ihr die Bestandteile zusammengetragen habt, damit wir mit dem ersten Arbeitsauftrag beginnen können.", sourceObjective = "Beginnt Euren ersten Arbeitsauftrag für Lederverarbeitung bei der Gerberei und holt ihn anschließend ab.", progress = "Ja?", completion = "Lasst mich das für Euch auspacken.\n\nWir haben diesen Auftrag zwar schneller bearbeitet, aber Ihr solltet wissen, dass zukünftige Arbeitsaufträge zur Fertigstellung länger benötigen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[36643] = { id = 36643, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Euer erster Arbeitsauftrag für Schneiderei", description = "Jetzt, da Eure Maßschneiderei fertiggestellt ist, können wir Hexenzwirn für Euch fertigen. Sprecht mit meiner Tochter, wenn Ihr die Bestandteile zusammengetragen habt, damit wir mit dem ersten Arbeitsauftrag beginnen können.", sourceObjective = "Beginnt Euren ersten Arbeitsauftrag für Schneiderei bei der Maßschneiderei und holt ihn anschließend ab.", progress = "Ja?", completion = "Lasst mich das für Euch auspacken.\n\nWir haben diesen Auftrag zwar schneller bearbeitet, aber Ihr solltet wissen, dass zukünftige Arbeitsaufträge zur Fertigstellung länger benötigen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[36644] = { id = 36644, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Euer erster Arbeitsauftrag für Juwelierskunst", description = "Jetzt, da Ihr über eine Juwelenschleiferei verfügt, können wir Taladitkristalle für Euch fertigen. Sprecht mit meiner Gehilfin, wenn Ihr die Bestandteile zusammengetragen habt, damit wir mit dem ersten Arbeitsauftrag beginnen können.", sourceObjective = "Beginnt Euren ersten Arbeitsauftrag für Juwelierskunst bei der Juwelenschleiferei und holt ihn anschließend ab.", progress = "Ja?", completion = "Lasst mich das für Euch auspacken.\n\nWir haben diesen Auftrag zwar schneller bearbeitet, aber Ihr solltet wissen, dass zukünftige Arbeitsaufträge zur Fertigstellung länger benötigen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[36645] = { id = 36645, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Euer erster Arbeitsauftrag für Verzauberkunst", description = "Jetzt, da Ihr über ein Verzauberungsatelier verfügt, können wir draenischen Staub für Euch fertigen. Sprecht mit meinem Gehilfen, wenn Ihr die Bestandteile zusammengetragen habt, damit wir mit dem ersten Arbeitsauftrag beginnen können.", sourceObjective = "Beginnt Euren ersten Arbeitsauftrag für Verzauberkunst beim Verzauberungsatelier und holt ihn anschließend ab.", progress = "Ja?", completion = "Lasst mich das für Euch auspacken.\n\nWir haben diesen Auftrag zwar schneller bearbeitet, aber Ihr solltet wissen, dass zukünftige Arbeitsaufträge zur Fertigstellung länger benötigen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[36646] = { id = 36646, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Euer erster Arbeitsauftrag für Ingenieurskunst", description = "Jetzt, da Ihr über ein Ingenieurlabor verfügt, können wir Getriebefederteile für Euch fertigen. Sprecht mit meiner Gehilfin, wenn Ihr die Bestandteile zusammengetragen habt, damit wir mit dem ersten Arbeitsauftrag beginnen können.", sourceObjective = "Beginnt Euren ersten Arbeitsauftrag für Ingenieurskunst beim Ingenieurlabor und holt ihn anschließend ab.", progress = "Ja?", completion = "Lasst mich das für Euch auspacken.\n\nWir haben diesen Auftrag zwar schneller bearbeitet, aber Ihr solltet wissen, dass zukünftige Arbeitsaufträge zur Fertigstellung länger benötigen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[36647] = { id = 36647, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Euer erster Arbeitsauftrag für Inschriftenkunde", description = "Jetzt, da Ihr über eine Schreibstube verfügt, können wir Kriegsfarben für Euch fertigen. Sprecht mit meinem Bruder, wenn Ihr die Bestandteile zusammengetragen habt, damit wir mit dem ersten Arbeitsauftrag beginnen können.", sourceObjective = "Beginnt Euren ersten Arbeitsauftrag für Inschriftenkunde bei der Schreibstube und holt ihn anschließend ab.", progress = "Ja?", completion = "Lasst mich das für Euch auspacken.\n\nWir haben diesen Auftrag zwar schneller bearbeitet, aber Ihr solltet wissen, dass zukünftige Arbeitsaufträge zur Fertigstellung länger benötigen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[36648] = { id = 36648, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf die Steinzornklippen", description = "Oger der Blutschläger vom Frostfeuergrat überfallen Handelsrouten überall auf dem Kontinent und zwingen gefangene Soldaten, in ihren Schlackeminen zu arbeiten.\n\nBodrick Grau hat befohlen, verbündete Truppen zu befreien, die als Zwangsarbeiter im Hauptlager der Blutschläger an den Steinzornklippen arbeiten.", sourceObjective = "Greift die Oger der Blutschläger in den Steinzornklippen am Frostfeuergrat an.", completion = "Es machen bereits Nachrichten über den Angriff die Runde, genauso wie ein Teil der Kriegsbeute.\n\nGute Arbeit, Kommandant, wenn ich so frei sein darf.", sourceObjectiveStatus = "unverified-source-field" }
quests[36649] = { id = 36649, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf den Hafen von Shattrath", description = "Shattrath ist in die Hände der Sargereitruppen gefallen, die von dem verräterischen Exarchen Socrethar angeführt werden.\n\nDie Mitglieder der Sha'tarverteidigung haben um Unterstützung gegen die Truppen des Schattenrates im Ostteil der Stadt gebeten.", sourceObjective = "Greift die Sargereitruppen in Shattrath in Talador an.", completion = "Es machen bereits Nachrichten über den Angriff die Runde, genauso wie ein Teil der Kriegsbeute.\n\nGute Arbeit, Kommandant, wenn ich so frei sein darf.", sourceObjectiveStatus = "unverified-source-field" }
quests[36650] = { id = 36650, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogerinvasion!", description = "Späher melden, dass Ogerrudel durch das Schattenmondtal marschieren. Wie es scheint, wir haben wir Eindruck gemacht. Was meint Ihr, Kommandant?", sourceObjective = "Schlagt die Invasion Eurer Garnison durch die Oger zurück.\n\n(Sprecht erneut mit Unteroffizier Krähler, um zu beginnen.)", progress = "Wir müssen die Stellung halten!", completion = "Ein Schläger lernt am besten, indem er sich eine blutige Nase holt! Toller Kampf, Kommandant. Euch zu dienen, ist eine Ehre.", sourceObjectiveStatus = "unverified-source-field" }
quests[36651] = { id = 36651, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: SHarvest Crystal" }
quests[36653] = { id = 36653, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invasion der Botani!", description = "Die Luft ist schwer. Erinnert mich an Schlachten im Schlingendorntal. Der Dschungelkrieg eignet sich gut für Axtkämpfe.", sourceObjective = "Schlagt die Invasion Eurer Garnison durch die Botani zurück.\n\n(Sprecht erneut mit Unteroffizier Grimmkinn, um zu beginnen.)", sourceObjectiveStatus = "unverified-source-field" }
quests[36654] = { id = 36654, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Lost Dwarf" }
quests[36655] = { id = 36655, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invasion der Eisernen Horde!", description = "Am Horizont steigt Rauch auf... Die Eiserne Horde ist im Anmarsch.", sourceObjective = "Sprecht mit Unteroffizier Krähler.", progress = "Schlagt die Invasion der Eisernen Horde zurück.\n\n(Sprecht erneut mit Unteroffizier Krähler, um zu beginnen.)", completion = "Ich weiß nicht, was schlimmer ist: die Brutalität der Eisernen Horde oder die latente Bedrohung durch unsere alten Gegner. Ist auch egal. Beide sind Eurer Stärke nicht gewachsen, Kommandant.", sourceObjectiveStatus = "unverified-source-field" }
quests[36656] = { id = 36656, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Sunclaw" }
quests[36657] = { id = 36657, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Scubi-Du" }
quests[36658] = { id = 36658, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Botani Stockpile" }
quests[36659] = { id = 36659, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "TBD" }
quests[36660] = { id = 36660, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutmähnenrevier" }
quests[36662] = { id = 36662, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hauerei", description = "Seitdem wir die Menagerie gebaut hab'n, kommen immer mehr \"Besucher\". Ich kenn' die Blicke: Die wollen 'nen Kampf sehen. <Bruder/Schwester>, zeigt ihnen, dass Ihr hier Chef im Ring seid!", sourceObjective = "Besiegt die Haustiere in der Kampfarena.", progress = "Habt Ihr ihnen das Mojo gezeigt?", completion = "Denen habt Ihr's gezeigt, Boss!", sourceObjectiveStatus = "unverified-source-field" }
quests[36663] = { id = 36663, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garrison Max-level Choice Tracker: ANY CHOICE MADE" }
quests[36664] = { id = 36664, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garrison Max-level Choice Tracker: ANY CHOICE MADE" }
quests[36667] = { id = 36667, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf den Hafen von Shattrath", description = "Shattrath ist in die Hände der Sargereitruppen gefallen, die vom ehemaligen Exarchen Socrethar angeführt werden.\n\nDie Truppen des Schattenrates im Ostteil der Stadt gewinnen durch die Hilfe von Dämonen aus dem Nether an Stärke. Sie müssen ausgemerzt werden, bevor sie zu einer Bedrohung für all unsere Operationen werden können.", sourceObjective = "Greift die Sargereitruppen in Shattrath in Talador an.", sourceObjectiveStatus = "unverified-source-field" }
quests[36669] = { id = 36669, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf die Steinzornklippen", description = "Oger der Blutschläger aus dem Frostfeuergrat überfallen Handelsrouten auf dem ganzen Kontinent und zwingen gefangen genommene Soldaten zur Arbeit in ihren Blutschlägerminen.\n\nSchattenjäger Rokhan hat um die Rettung der befreundeten Truppen gebeten, die im Hauptarbeitslager der Blutschläger an den Steinzornklippen gefangen gehalten werden.", sourceObjective = "Greift die Oger der Blutschläger in den Steinzornklippen des Frostfeuergrats an.", completion = "Ich hab schon vom Angriff gehört, Scheff. Und auch von der Beute.\n\nEuch darf man nicht unterschätzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[36670] = { id = 36670, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ring des Blutes: Schädelbeißer!", description = "Willkommen in Nagrands einzigartigem Ring des Blutes, wo hoffnungsvolle Kämpfer zu Gladiatoren und Gladiatoren zu Hackfleisch auf dem Boden der Arena werden!\n\nSprecht mich vor Beginn eines Kampfs an, springt hinunter in den Ring und kämpft um Euer Leben. Es ist auf jeden Fall brutal, und die Menge liebt es!\n\nIhr werdet gegen einen Ogron antreten, der eine Vorliebe für frisch abgetrennte Häupter hat. Ihr werdet schon klarkommen... und ich werde reich!", sourceObjective = "Besiegt Schädelbeißer im Ring des Blutes.", sourceObjectiveStatus = "unverified-source-field" }
quests[36671] = { id = 36671, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ring des Blutes: Fracktus!", description = "Habt Ihr jemals gegen einen lebendigen, atmenden Berg gekämpft, der Euch den Garaus machen will? Nun, heute ist Euer Glückstag!\n\nFracktus ist... nun... ein lebendiger, atmender Berg, der Euch zur Abwechselung einfach nur töten will. Das war schon beim ersten Mal richtig!\n\nSpringt einfach in den Ring, damit wir anfangen können, ja?", sourceObjective = "Besiegt Fracktus im Ring des Blutes.", sourceObjectiveStatus = "unverified-source-field" }
quests[36672] = { id = 36672, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ring des Blutes: Venoxis!", description = "Schon gut, schon gut, wie wäre es hiermit. Ein lebendiger, atmender... Achtung, jetzt kommt's... Baum, der Eure Visage töten will. Genial, nicht wahr?\n\nHört mal, man bezahlt mich hier nicht, um jedes Mal ein paar witzige Sprüche über diese Dinger loszulassen, macht mal halblang. Das sind Oger. Die bezahlen für Blut. Daher auch der Name.", sourceObjective = "Besiegt Venoxis im Ring des Blutes.", sourceObjectiveStatus = "unverified-source-field" }
quests[36673] = { id = 36673, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ring des Blutes: Dreshax!", description = "Den nächsten werdet Ihr lieben, Champ.\n\nSo ist es, das ist der größte Knochenwurm dieser Hälfte von Draenor. Dreshax entsorgt liebevoll alle Schwächlin... ich meine gefallenen Gladiatoren für uns.\n\nMeint Ihr, Ihr habt es drauf? Dann springt rein und wartet. Dreshax' Versteck ist genau unter der Arena. Er wird zu Euch kommen.", sourceObjective = "Besiegt Dreshax im Ring des Blutes.", sourceObjectiveStatus = "unverified-source-field" }
quests[36674] = { id = 36674, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf das Eiserne Belagerungswerk", description = "Zu Dutzenden werden Kriegsmaschinen der Eisernen Horde auf die Schlachtfelder gekarrt. Unsere Truppen können die Stellung kaum halten. Die meisten Maschinen stammen offenbar aus dem Eisernen Belagerungswerk im östlichen Frostfeuergrat.\n\nMit einem strategischen Angriff auf das Belagerungswerk könnten wir die Eiserne Horde deutlich schwächen und den Krieg zu unseren Gunsten wenden.", sourceObjective = "Greift die Eiserne Horde in ihrem Belagerungswerk im Frostfeuergrat an.", sourceObjectiveStatus = "unverified-source-field" }
quests[36675] = { id = 36675, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf Magnarok", description = "Gewaltige Magnaron, Gronn und andere Monstrositäten aus Stein bedrohen unsere Außenposten im Westen. Wir nehmen an, dass die meisten von ihnen aus Magnarok im Frostfeuergrat stammen.\n\nWenn wir direkt in ihrer Heimat angreifen, sollten wir sie zurückdrängen können. Es ist riskant, aber könnte sich als die beste Strategie herausstellen. Vielleicht könnt Ihr dabei auch einige unserer Vorräte zurückholen.", sourceObjective = "Greift die Steinmonstrositäten bei Magnarok im Frostfeuergrat an.", completion = "Es machen bereits Nachrichten über den Angriff die Runde, genauso wie ein Teil der Kriegsbeute.\n\nGute Arbeit, Kommandantin, wenn ich so frei sein darf.", sourceObjectiveStatus = "unverified-source-field" }
quests[36676] = { id = 36676, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf die Immergrüne Wildnis", description = "Die Botani und ihre beschworenen Pflanzenmonstrositäten bedrohen unsere Außenposten im Norden immer mehr. Für jede Pflanze, die wir töten, scheint direkt eine neue nachzuwachsen.\n\nBodrick Grau hat einen Plan erdacht, die Immergrüne Wildnis anzugreifen, das Herz des Botaniterritoriums. Er glaubt, dass wir die Botani in die Wildnis von Gorgrond zurückdrängen können und so mehr Spielraum bekommen.", sourceObjective = "Greift die Botani in der Immergrünen Wildnis in Gorgrond an.", completion = "Es machen bereits Nachrichten über den Angriff die Runde, genauso wie ein Teil der Kriegsbeute.\n\nGute Arbeit, Kommandant, wenn ich so frei sein darf.", sourceObjectiveStatus = "unverified-source-field" }
quests[36677] = { id = 36677, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf die Zerschlagene Anhöhe", description = "Riesige Ogron machen unserer Front schwer zu schaffen. Ganz gleich, wie viele wir ausschalten, es werden immer nur noch mehr.\n\nDie meisten dieser Ogron stammen von der Zerschlagenen Anhöhe, ganz im Westen von Nagrand. Wir müssen sie von den Schlachtfeldern fernhalten, sonst werden wir in kommenden Schlachten keine Chance haben.", sourceObjective = "Greift die Streitkräfte der Ogron bei der Zerschlagenen Anhöhe in Nagrand an.", completion = "Es machen bereits Nachrichten über den Angriff die Runde, genauso wie ein Teil der Kriegsbeute.\n\nGute Arbeit, wenn ich so frei sein darf.", sourceObjectiveStatus = "unverified-source-field" }
quests[36678] = { id = 36678, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf den Wachposten von Mok'gol", description = "Räuber des Kriegshymnenklans aus dem Wachposten von Mok'gol terrorisieren alles und jeden, der sich nicht hinter einer hohen Mauer in Sicherheit bringen kann. Wir haben Reisende gewarnt, sich nicht allein auf den Weg zu machen, doch kaum einer hört auf uns.\n\nMit einem Angriff auf den Wachposten von Mok'gol könnten wir den Kriegshymnenklan mit großer Sicherheit nach Nagrand zurückdrängen.", sourceObjective = "Greift den Kriegshymnenklan am Wachposten von Mok'gol in Nagrand an.", completion = "Es machen bereits Nachrichten über den Angriff die Runde, genauso wie ein Teil der Kriegsbeute.\n\nGute Arbeit, Kommandant, wenn ich so frei sein darf.", sourceObjectiveStatus = "unverified-source-field" }
quests[36679] = { id = 36679, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf das Nachtflutnest", description = "In unseren Gefechten mit der Eisernen Horde kämpfen immer mehr Rylaks. Wenn wir dem keinen Riegel vorschieben, werden wir schnell die Kontrolle über die Straßen verlieren und in unsere Außenposten zurückgedrängt werden.\n\nDiese zusätzlichen Rylaks stammen wahrscheinlich aus dem Nachtflutnest im südöstlichen Schattenmondtal. Wenn wir uns beeilen, könnten wir dem Problem rechtzeitig ein Ende setzen.", sourceObjective = "Greift die Truppen der Eisernen Horde beim Nachtflutnest im Schattenmondtal an.", completion = "Es machen bereits Nachrichten über den Angriff die Runde, genauso wie ein Teil der Kriegsbeute.\n\nGute Arbeit, Kommandant, wenn ich so frei sein darf.", sourceObjectiveStatus = "unverified-source-field" }
quests[36680] = { id = 36680, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf Socrethars Klippe", description = "Aktuellen Berichten zufolge sind die Sargerei bei Socrethars Klippe im südlichen Schattenmondtal in letzter Zeit deutlich aktiver.\n\nSocrethars Anhänger stellen sowohl für die Draenei als auch für unsere Garnison ein Problem dar. Wir müssen sie so bald wie möglich bezwingen.", sourceObjective = "Greift die Sargereistreitkräfte auf Socrethars Klippe im Schattenmondtal an.", completion = "Es machen bereits Nachrichten über den Angriff die Runde, genauso wie ein Teil der Kriegsbeute.\n\nGute Arbeit, Kommandant, wenn ich so frei sein darf.", sourceObjectiveStatus = "unverified-source-field" }
quests[36681] = { id = 36681, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf das Vergessene Anzuversteck", description = "Ein paar unserer besten Späher werden in der Nähe der vergessenen Ruinen des Anzuverstecks vermisst.\n\nBodrick Grau bittet darum, alle verfügbaren Ressourcen zu entsenden, um die Bedrohung zu identifizieren und herauszufinden, ob in den Ruinen noch welche von unseren Männern am Leben sind.", sourceObjective = "Greift die feindlich gesinnten Kreaturen im Vergessenen Anzuversteck in den Spitzen von Arak an.", completion = "Es machen bereits Nachrichten über den Angriff die Runde, genauso wie ein Teil der Kriegsbeute.\n\nGute Arbeit, Kommandant, wenn ich so frei sein darf.", sourceObjectiveStatus = "unverified-source-field" }
quests[36682] = { id = 36682, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf die Säulen des Schicksals", description = "In den Anhöhen an den östlichen Grenzen der Spitzen von Arak sind weiterhin vereinzelte Truppen des Schattenmondklans aktiv, die von dort aus operieren.\n\nBodrick Grau sieht dies mit Unbehagen, vor allem wegen ihrer Nähe zu unserer Garnison, und hat daher angeordnet, dass wir so bald wie möglich gegen diese Truppenansammlungen vorgehen.", sourceObjective = "Greift die Schattenmondorcs bei den Säulen des Schicksals im Schattenmondtal an.", completion = "Es machen bereits Nachrichten über den Angriff die Runde, genauso wie ein Teil der Kriegsbeute.\n\nGute Arbeit, Kommandant, wenn ich so frei sein darf.", sourceObjectiveStatus = "unverified-source-field" }
quests[36683] = { id = 36683, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf Skettis", description = "Wir erhalten vermehrt Berichte, dass Vogelmenschen aus dem Süden auf den Hauptstraßen Karawanen überfallen.\n\nDie Wachen in den Außenposten fordern, dass wir in Skettis an den Spitzen von Arak einen Gegenangriff gegen die Hauptkräfte der Jünger von Rukhmar führen.", sourceObjective = "Greift die Jünger von Rukhmar in Skettis an den Spitzen von Arak an.", completion = "Es machen bereits Nachrichten über den Angriff die Runde, genauso wie ein Teil der Kriegsbeute.\n\nGute Arbeit, Kommandant, wenn ich so frei sein darf.", sourceObjectiveStatus = "unverified-source-field" }
quests[36684] = { id = 36684, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlacht um Ashran", description = "Während wir in ganz Draenor Krieg führen, versucht die feige Horde, sich unser Territorium in Ashran anzueignen.\n\nEs würde eine Inspiration für unsere Truppen darstellen, wenn Ihr Euch dem Schlachtgeschehen anschließt und der Horde ein wenig Angst einflößt.", sourceObjective = "Schließt Euch dem Kampf in Ashran an.", sourceObjectiveStatus = "unverified-source-field" }
quests[36685] = { id = 36685, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf das Herz von Shattrath", description = "Truppen der Sargerei aus dem Inneren Shattraths werden mit jedem Tag stärker und wagemutiger. Sie stellen ein Risiko dar, das wir nicht länger ignorieren können.\n\nWenn Ihr Euch den Sargerei im Herzen der Stadt stellen wollt, solltet Ihr Verbündete mitbringen.", sourceObjective = "Greift die Sargerei in Shattrath in Talador an.", completion = "Es machen bereits Nachrichten über den Angriff die Runde, genauso wie ein Teil der Kriegsbeute.\n\nGute Arbeit, der Herr, wenn ich so frei sein darf.", sourceObjectiveStatus = "unverified-source-field" }
quests[36686] = { id = 36686, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf die Grube", description = "Die Schwarzfelsstreitkräfte aus der Grube in Gorgrond bilden einen Großteil der Armee der Eisernen Horde. Wenn wir sie auf ihrem eigenen Grund und Boden ausmerzen, wird der Rest der Eisernen Horde kaum eine Chance haben, gegen uns zu bestehen.\n\nWenn Ihr diesen Kampf ausfechten wollt, dann bringt einige Freunde mit. Die Schwarzfelsorcs sind keine einfachen Widersacher.", sourceObjective = "Greift die Schwarzfelsorcs in der Grube in Gorgrond an.", completion = "Es machen bereits Nachrichten über den Angriff die Runde, genauso wie ein Teil der Kriegsbeute.\n\nGute Arbeit, der Herr, wenn ich so frei sein darf.", sourceObjectiveStatus = "unverified-source-field" }
quests[36687] = { id = 36687, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herausforderung im Ring des Blutes", description = "Im Ring des Blutes wartet eine Herausforderung auf Euch.\n\nHolt Euch die Unterstützung Eurer Freunde und stellt Euer Recht als Champion im Kampf unter Beweis.", sourceObjective = "Stellt Euch dem Kampf im Ring des Blutes.", sourceObjectiveStatus = "unverified-source-field" }
quests[36688] = { id = 36688, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf Skettis", description = "Wir erhalten vermehrt Berichte, dass Vogelmenschen aus dem Süden auf den Hauptstraßen Karawanen überfallen.\n\nDie Wachen in den Außenposten fordern, dass wir in Skettis an den Spitzen von Arak einen Gegenangriff gegen die Hauptstreitkräfte der Jünger von Rukhmar führen.", sourceObjective = "Greift die Arakkoastreitkräfte in Skettis an den Spitzen von Arak an.", completion = "Ich hab schon vom Angriff gehört, Scheff. Und auch von der Beute.\n\nEuch darf man nicht unterschätzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[36689] = { id = 36689, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf die Säulen des Schicksals", description = "In den Anhöhen an den östlichen Grenzen der Spitzen von Arak sind weiterhin vereinzelte Truppen des Schattenmondklans aktiv, die von dort aus operieren.\n\nRokhan ist besorgt, weil sie sich so nah bei wichtigen Routen ins Schattenmondtal aufhalten. Er hat angeordnet, dass wir so bald wie möglich gegen diese Truppenansammlungen vorgehen.", sourceObjective = "Greift die Schattenmondtruppen bei den Säulen des Schicksals im Schattenmondtal an.", completion = "Ich hab schon vom Angriff gehört, Scheff. Und auch von der Beute.\n\nEuch darf man nicht unterschätzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[36690] = { id = 36690, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf das Vergessene Anzuversteck", description = "Ein paar unserer besten Späher werden in der Nähe der vergessenen Ruinen des Anzuverstecks vermisst.\n\nRokhan bittet darum, alle verfügbaren Ressourcen zu entsenden, um die Bedrohung zu identifizieren und herauszufinden, ob in den Ruinen noch welche von unseren Männern am Leben sind.", sourceObjective = "Greift die feindlich gesinnten Kreaturen im Vergessenen Anzuversteck in den Spitzen von Arak an.", progress = "Mit dem Angriff klappt's, hoffe ich?", completion = "Ich hab schon vom Angriff gehört, Scheff. Und auch von der Beute.\n\nEuch darf man nicht unterschätzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[36691] = { id = 36691, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf Socrethars Klippe", description = "Aktuellen Berichten zufolge sind die Sargerei bei Socrethars Klippe im südlichen Schattenmondtal in letzter Zeit deutlich aktiver.\n\nSocrethars Anhänger sind eine Bedrohung für ganz Draenor. Wir dürfen nicht zulassen, dass sie außerhalb unserer Reichweite Fuß fassen.", sourceObjective = "Greift die Sargereistreitkräfte auf Socrethars Klippe im Schattenmondtal an.", completion = "Ich hab schon vom Angriff gehört, Scheffin. Und auch von der Beute.\n\nEuch darf man nicht unterschätzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[36692] = { id = 36692, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf das Nachtflutnest", description = "In unseren Gefechten mit der Eisernen Horde tauchen mehr und mehr Rylaks auf den Schlachtfeldern auf. Wenn wir dem keinen Riegel vorschieben, werden wir schnell die Kontrolle über die Straßen verlieren und so in unsere Außenposten zurückgedrängt werden.\n\nDiese zusätzlichen Rylaks stammen höchstwahrscheinlich aus dem Nachtflutnest im Südosten des Schattenmondtals. Wenn wir uns beeilen, können wir das Problem vielleicht im Keim ersticken.", sourceObjective = "Greift die Truppen der Eisernen Horde beim Nachtflutnest im Schattenmondtal an.", completion = "Ich hab schon vom Angriff gehört, Scheff. Und auch von der Beute.\n\nEuch darf man nicht unterschätzen.", sourceObjectiveStatus = "unverified-source-field" }
