quests[36695] = { id = 36695, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf die Immergrüne Wildnis", description = "Die Botani und ihre beschworenen Pflanzenmonstrositäten bedrohen unsere Außenposten im Norden immer mehr. Für jede Pflanze, die wir töten, scheint direkt eine neue nachzuwachsen.\n\nRokhan hat einen Plan ersonnen, um mitten in ihrem Gebiet, in der Immergrünen Wildnis, zuzuschlagen. Er glaubt, die Botani ziehen sich dann in die Dschungel von Gorgrond zurück und wir bekommen mehr Spielraum.", sourceObjective = "Greift die Botani in der Immergrünen Wildnis in Gorgrond an.", completion = "Ich hab schon vom Angriff gehört, Scheffin. Und auch von der Beute.\n\nEuch darf man nicht unterschätzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[36696] = { id = 36696, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf das Eiserne Belagerungswerk", description = "Zu Dutzenden werden Kriegsmaschinen der Eisernen Horde auf die Schlachtfelder gekarrt. Unsere Truppen können die Stellung kaum halten. Die meisten Maschinen stammen offenbar aus dem Eisernen Belagerungswerk im östlichen Frostfeuergrat.\n\nMit einem strategischen Angriff auf das Belagerungswerk könnten wir die Eiserne Horde deutlich schwächen und den Krieg zu unseren Gunsten wenden.", sourceObjective = "Greift die Eiserne Horde in ihrem Belagerungswerk im Frostfeuergrat an.", sourceObjectiveStatus = "unverified-source-field" }
quests[36697] = { id = 36697, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf Magnarok", description = "Riesige Magnaron, Gronn und andere Steinmonstrositäten bedrohen unsere Garnison. Die meisten kommen aus Magnarok ein Stück weit im Norden.\n\nWenn wir in ihrer Heimat gegen sie vorgehen, müssten wir sie zurückdrängen können. Es ist riskant, aber vielleicht unsere beste Option. Während Ihr dort seid, versucht, ein paar unserer Vorräte zurückzuerlangen.", sourceObjective = "Greift die Steinmonstrositäten bei Magnarok im Frostfeuergrat an.", completion = "Ich hab schon vom Angriff gehört, Scheff. Und auch von der Beute.\n\nEuch darf man nicht unterschätzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[36698] = { id = 36698, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlacht um Ashran", description = "Während wir in ganz Draenor Krieg führen, versucht die feige Allianz, sich unser Territorium in Ashran anzueignen.\n\nEs würde eine Inspiration für unsere Truppen darstellen, wenn Ihr Euch dem Kampfgeschehen anschließen und Angst in die Herzen der Allianz tragen würdet.", sourceObjective = "Schließt Euch dem Kampf in Ashran an.", sourceObjectiveStatus = "unverified-source-field" }
quests[36699] = { id = 36699, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf das Herz von Shattrath", description = "Truppen der Sargerei aus dem Inneren Shattraths werden mit jedem Tag stärker und wagemutiger. Sie stellen ein Risiko dar, das wir nicht länger ignorieren können.\n\nWenn Ihr Euch den Sargerei im Herzen der Stadt stellen wollt, solltet Ihr Verbündete mitbringen.", sourceObjective = "Greift die Sargereitruppen in Shattrath in Talador an.", completion = "Ich hab schon vom Angriff gehört, Scheff. Und auch von der Beute.\n\nEuch darf man nicht unterschätzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[36700] = { id = 36700, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herausforderung im Ring des Blutes", description = "Im Ring des Blutes wartet eine Herausforderung auf Euch.\n\nHolt Euch die Unterstützung Eurer Freunde und stellt Euer Recht als Champion im Kampf unter Beweis.", sourceObjective = "Stellt Euch dem Kampf im Ring des Blutes.", sourceObjectiveStatus = "unverified-source-field" }
quests[36701] = { id = 36701, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf die Grube", description = "Die Schwarzfelsstreitkräfte aus der Grube in Gorgrond bilden einen Großteil der Armee der Eisernen Horde. Wenn wir sie an ihrem Heimatort ausmerzen, wird der Rest der Eisernen Horde kaum eine Chance haben, gegen uns zu bestehen.\n\nWenn Ihr diesen Kampf ausfechten wollt, dann bringt einige Freunde mit. Die Schwarzfelsorcs sind nicht so einfach zu besiegen.", sourceObjective = "Greift die Schwarzfelstruppen in der Grube in Gorgrond an.", completion = "Ich hab schon vom Angriff gehört, Scheff. Und auch von der Beute.\n\nEuch darf man nicht unterschätzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[36702] = { id = 36702, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fleischklops", sourceObjective = "FLEISCHKLOPS FÜHLT SICH JETZT BESSER!\n\nFLEISCHKLOPS KÄMPFT JETZT FÜR MAAKA!\n\nFLEISCHKLOPS FOLGT MAAKA ÜBERALL HIN!!!", sourceObjectiveStatus = "unverified-source-field" }
quests[36705] = { id = 36705, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ring des Blutes: Mogor!", description = "Diesmal habt Ihr es wirklich geschafft, Champ. Mogor hat Euch herausgefordert, um seinen Titel als Herr des Rings zu verteidigen!\n\nIch wünschte, ich könnte Euch Ratschläge erteilen, wie Ihr in einem Stück da rauskommt, aber ich habe Mogor noch nie kämpfen sehen. Niemand hat es je soweit geschafft!\n\nViel Glück.", sourceObjective = "Besiegt Mogor im Ring des Blutes.", sourceObjectiveStatus = "unverified-source-field" }
quests[36706] = { id = 36706, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auftritt in Ashran", description = "Unsere Ashranbasis ist fast fertig, Kommandant.\n\nIhr würdet ein bedeutendes Zeichen der Unterstützung setzen, wenn Ihr dorthin reist und Eure Genehmigung für den Stützpunkt persönlich überbringt.\n\nIch kann einen Flug für Euch in die Wege leiten, wenn Ihr möchtet.", sourceObjective = "Sprecht mit dem Gefreiten Stampfhuf beim Kriegsspeer in Ashran.", completion = "Kommandant! Ich bin Euer demütiger Diener. Der Leutnant bittet um Eure Anwesenheit.", sourceObjectiveStatus = "unverified-source-field" }
quests[36707] = { id = 36707, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsspeerwillkommen", description = "Leutnant Kragil sagte, dass Ihr vielleicht vorbeischaut.\n\nIch habe Befehl, Euch zum Gasthaus zu bringen.", sourceObjective = "Sprecht mit Leutnant Kragil.", completion = "Throm-Ka, Kommandant. Ich bin erfreut, Euch endlich persönlich kennenzulernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[36708] = { id = 36708, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inspiration für Ashran", description = "Ich hoffe, dass unsere Anlagen Euren hohen Ansprüchen genügen.\n\nDieses Gasthaus wird von Narnin Morgendämmerung geleitet, und meiner Meinung nach ist es der beste Ruheplatz in ganz Draenor.\n\nTäglich kommen neue Rekruten durch das Portal. Unser neuester Rekrut, Zarjhin, ist gerade heute durch das Portal gekommen.\n\nWenn Ihr handeln wollt, um Waffen oder Rüstung zu erwerben, wird Beska Rothauer Euch sicher gerne weiterhelfen.", sourceObjective = "Sprecht mit Narnin Morgendämmerung, Beska Rothauer und Zarjhin.", progress = "Wie war Euer Spaziergang?", completion = "Ich danke Euch nochmals, dass Ihr die Zeit für einen Besuch erübrigen konntet, Kommandant. Ihr wisst ja nicht, wie viel uns das bedeutet.", sourceObjectiveStatus = "unverified-source-field" }
quests[36709] = { id = 36709, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brennende Schönheit", description = "Bevor Ihr geht, solltet Ihr noch jemanden treffen.\n\nSie wird vielleicht etwas von Eurem Zeug in Brand stecken, aber ich glaube, sie ist die beste Magierin in diesem Teil von Draenor.\n\nSie gehört an Eurer Seite an die Front, Kommandant.", sourceObjective = "Sprecht mit Vivianne.", completion = "Also Ihr seid der Kommandant? Sylvanas hat mich geschickt.", sourceObjectiveStatus = "unverified-source-field" }
quests[36710] = { id = 36710, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking: Arena Treasure 1" }
quests[36711] = { id = 36711, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abu'gar", progress = "Also Ihr glaubt, dass Ihr mir helfen könnt, Mann?", completion = "Ihr habt mein Zeug mitgebracht! Nun, da scheint mir das Glück doch wieder hold zu sein!\n\nAbu'gar wird sich revanchieren, wartet nur ab!\n\nDirekt nachdem ich mir einen Oschi an die Angel geholt habe..." }
