quests[36718] = { id = 36718, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking: Mill Treasure 24" }
quests[36719] = { id = 36719, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu Aegwynns Zuflucht", description = "Um diesen Dämon zu bezwingen, benötigen wir etwas, das uns auf eine Stufe mit ihm bringt. Etwas... Mächtiges...\n\n<Khadgar betrachtet nachdenklich seinen Stab Atiesh.>\n\nIhr braucht eine Waffe, die mit viel Macht erfüllt ist. Und wenn ich mit meinen Vermutungen richtigliege, könntet Ihr eine solche ganz in der Nähe ausfindig machen.\n\nIch kann Euch auf den Weg schicken, um diese Waffe zu finden. Sprecht mit mir, wenn Ihr dafür bereit seid.", sourceObjective = "Sprecht mit Khadgar.", sourceObjectiveStatus = "unverified-source-field" }
quests[36720] = { id = 36720, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking: Mill Treasure 25" }
