quests[36725] = { id = 36725, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Makellose Frostwolfaxt mit Bissspuren", description = "Dieses Artefakt wurde restauriert und ist nun in bemerkenswert gutem Zustand. Ihr könnt es jetzt in Eurer Garnison ausstellen.", sourceObjective = "Stellt das Artefakt zur Schau.", sourceObjectiveStatus = "unverified-source-field" }
