quests[36741] = { id = 36741, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klassischer Trank der freien Aktion", description = "Wie ich höre, werden unsere Helden an der Front Opfer von übermäßig vielen Verlangsamungs-, Bewegungsunfähigkeits- und Betäubungszaubern! Zum Glück habe ich den richtigen Trank für sie. Das Rezept ist zwar etwas älter, aber er wird wirken.\n\nEine dafür benötigte Hauptzutat gibt es hier in Ashran am Strand in der Nähe des Ogerturms.", sourceObjective = "Bringt Gimlett Ginfizz 10 Aschehammerperlen.", sourceObjectiveStatus = "unverified-source-field" }
quests[36742] = { id = 36742, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klassischer Trank der freien Aktion", description = "Die Allianz hat die Anzahl von hinderlichen Effekten gegen unsere Nahkämpfer beträchtlich erhöht.\nZum Glück habe ich den richtigen Trank für sie. Das Rezept ist zwar etwas älter, aber es wird funktionieren.\n\nEine dafür benötigte Hauptzutat gibt es hier in Ashran am Strand in der Nähe des Ogerturms.", sourceObjective = "Bringt Tyra Silberblut 10 Aschehammerperlen.", sourceObjectiveStatus = "unverified-source-field" }
