quests[36789] = { id = 36789, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking: Arena Treasure 25" }
quests[36790] = { id = 36790, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rache des Initianden", description = "Ich... ich kann nicht mehr. Bald wird mein Geist bei der Rabenmutter sein.\n\nIch flehe Euch an... rächt mich, <Fremder/Fremde>! Tötet diese elenden Bestien.", sourceObjective = "Tötet 18 Blutmähnensaberon.", completion = "Im Schwarm ist jedes Leben kostbar.\nIch bin froh, dass seinen Mördern Gerechtigkeit widerfahren ist.\n\nHabt Dank, {name}, Ihr habt uns einen ehrenwerten Dienst erwiesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[36791] = { id = 36791, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Phantomtrank", description = "Jedes Mal, wenn man sich in Ashran umdreht, gerät man in Schwierigkeiten. Aber keine Angst, {name}, ich habe die perfekte Lösung entwickelt: meine ganz persönliche Version des beliebten Unsichtbarkeitstranks.\n\nMir fehlt nur noch eine Zutat: Höhlenpilze.\n\nZum Glück wächst eine Sorte davon hier in Ashran.", sourceObjective = "Bringt Gimlett Ginfizz 10 Geistertrüffel.", sourceObjectiveStatus = "unverified-source-field" }
quests[36792] = { id = 36792, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Messerfaustfestung" }
quests[36793] = { id = 36793, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gegründete Garnison" }
quests[36794] = { id = 36794, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Sylldross" }
quests[36796] = { id = 36796, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rache der Krähen", description = "Die Blutmähnen haben einige unserer Initianden entführt, als sie unser Ritual im Rabenskar überfielen. Wir müssen Ihnen zeigen, dass der Schwarm eine solche Tat nicht ungestraft lassen wird!\n\nFür jeden Gefallenen aus unserem Schwarm werden sie mit einem Mitglied ihres Stamms zahlen!\n\nBegebt Euch zu ihnen ins Blutmähnental und tötet so viele von ihnen, wie ihr finden könnt.", sourceObjective = "Tötet 18 Saberon der Blutmähnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[36797] = { id = 36797, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gegründete Garnison" }
quests[36798] = { id = 36798, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scubi-Du" }
quests[36799] = { id = 36799, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garrison Nodes - Tracking Quest" }
quests[36800] = { id = 36800, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oschi der Feuerammoniten", progress = "Juchu! Das nenn ich einen Oschi, {name}! Ich glaube zwar nicht, dass ich mich jemals an das Angeln in Lava gewöhnen werde, aber wirklich normal ist an diesem verrückten Ort sowieso nichts.", completion = "Ich werde Euch jeden Oschi, den Ihr fangt, abnehmen. Ihr könnt mit solch einem Fang jederzeit wiederkommen und gutes Geld dafür erhalten!" }
quests[36801] = { id = 36801, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Schritt voraus", description = "Kommandant, Verteidiger Maraad ist mit Yrel und Thaelin Schwarzamboss aufgebrochen, um die Bewegungen der Eisernen Horde im nahegelegenen Wald zu verfolgen.\n\nSie erwarten Euch auf einer kleinen Anhöhe im Südwesten.", sourceObjective = "Sprecht mit Verteidiger Maraad auf der Erlösungsanhöhe.", completion = "Ah, Kommandant {name}. Schön, Euch zu sehen. Jetzt sind wir vollzählig.", sourceObjectiveStatus = "unverified-source-field" }
quests[36802] = { id = 36802, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oschi der Tiefsee", progress = "Ich bin überrascht, Euch in einem Stück wiederzusehen! Bei den Arakkoa der Spitzen von Arak sind Tiefenschluckaale eine Delikatesse.", completion = "Ich werde Euch jeden Oschi, den Ihr fangt, abnehmen. Ihr könnt mit solch einem Fang jederzeit wiederkommen und gutes Geld dafür erhalten!" }
quests[36803] = { id = 36803, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oschi des Schwarzwassers", progress = "Haben Euch diese Draenei drüben in Talador belästigt? Ich würde sie nie als Fischer bezeichnen, aber es heißt, dass sie sich mit den Angelplätzen vor Ort recht gut auskennen sollen. Doch das spielt keine Rolle, offenbar habt Ihr diesmal den Preis ergattert!", completion = "Ich werde Euch jeden Oschi, den Ihr fangt, abnehmen. Ihr könnt mit solch einem Fang jederzeit wiederkommen und gutes Geld dafür erhalten!" }
quests[36804] = { id = 36804, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blinder Seeoschi", progress = "Das ist mal ein feiner blinder Seeoschi, den Ihr da habt, {name}. Wie lange musstet Ihr mit ihm kämpfen? Fische wie diesen hier findet man nur selten, aber wenn, wird es ein Kampf!", completion = "Ich werde Euch jeden Oschi, den Ihr fangt, abnehmen. Ihr könnt mit solch einem Fang jederzeit wiederkommen und gutes Geld dafür erhalten!" }
quests[36805] = { id = 36805, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dicker Schläferoschi", progress = "Ihr habt da offenbar einen dicken Schläferoschi gefangen. Das kann das Flussangeln in Nagrand nicht schlagen, aber ich hoffe, dass ich es bald schaffe, einmal selbst nach dort draußen zu kommen.", completion = "Ich werde Euch jeden Oschi, den Ihr fangt, abnehmen. Ihr könnt mit solch einem Fang jederzeit wiederkommen und gutes Geld dafür erhalten!" }
quests[36806] = { id = 36806, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kieferloser Laueroschi", progress = "Ein kieferloser Laueroschi? Ich muss unbedingt in Gorgrond angeln gehen! Ich habe gehört, dass dort draußen viele Dinge zu enormer Größe anwachsen...", completion = "Ich werde Euch jeden Oschi, den Ihr fangt, abnehmen. Ihr könnt mit solch einem Fang jederzeit wiederkommen und gutes Geld dafür erhalten!" }
quests[36807] = { id = 36807, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf das Herz von Shattrath" }
quests[36808] = { id = 36808, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf den Hafen von Shattrath" }
quests[36809] = { id = 36809, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf das Herz von Shattrath" }
quests[36811] = { id = 36811, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückeroberung von Faronaar" }
quests[36812] = { id = 36812, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wer die Penny nicht ehrt, ist des Talers nicht wert", sourceObjective = "Ihr seid gute Leute, Kommandant.", sourceObjectiveStatus = "unverified-source-field" }
quests[36813] = { id = 36813, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zersetzender Befall", description = "Als Herr des Immergrünen Flors war es meine Aufgabe, die Natur in Waffen zu verwandeln.\n\nIhr habt wahrscheinlich die Früchte meiner Arbeit während Eurer Reisen durch meine Welt gesehen.\n\nMeine Entdeckungen haben es meinem Volk erlaubt, die eindringenden Spezies von Draenor durch zersetzenden Befall unter Kontrolle zu halten. Ich spreche von absoluter systemischer Kontrolle des einfallenden Organismus... über Geist und Körper.\n\nJetzt, da Ihr <mein Meister/meine Meisterin> seid, biete ich Euch diese Fähigkeiten an, aber zunächst müsst Ihr meine Forschungen und meine Werkzeuge aus dem Immergrünen Flor bergen.\n\nWenn Ihr das tut, wird Euch große Macht zuteilwerden.", sourceObjective = "Bergt die Forschung des Phylarchen, Xeri'tacs Giftdrüse und 3 ausgelaugte immergrüne Samen aus dem Immergrünen Flor und bringt sie zu Phylarch dem Immergrünen.", progress = "Bringt mir, wonach ich verlangt habe, Meister. Ich werde Euch die wahre Stärke der Natur zeigen.", completion = "In dieses Säckchen habe ich drei immergrüne Samen gelegt. Ihr müsst die Samen nur zerstampfen, um die Sporen darin freizusetzen. Atmet tief ein und lasst den zersetzenden Befall seinen Lauf nehmen.\n\nSobald Ihr einmal die Macht erhalten habt, werdet Ihr zu einer unaufhaltsamen Naturgewalt. Ich muss Euch jedoch warnen: Ich habe diese Samen verändert, damit sie Euch nur wenig Schaden zufügen. Dadurch ist ihre Wirksamkeit etwas geringer.\n\nIhr dürft die Verwandlung nicht zu häufig durchführen.\n\nSolltet Ihr noch weitere Samen benötigen, werde ich sie Euch zu einem günstigen Preis anbieten.", sourceObjectiveStatus = "unverified-source-field" }
quests[36814] = { id = 36814, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf die Immergrüne Wildnis" }
