quests[36828] = { id = 36828, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht genügend Holz", sourceObjective = "Tretet sie, wenn sie am Boden liegen!", sourceObjectiveStatus = "unverified-source-field" }
quests[36829] = { id = 36829, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talador - Shore Treasure - Gift of the Ancients" }
quests[36830] = { id = 36830, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattenratinvasion!", description = "Die Dämonen sind uns auf den Fersen, Kommandant. Die Milch der Kuh ist sauer. Ein altes Weib hat mich heute Morgen schief angeguckt. Der Himmel sieht einfach nicht... richtig aus.", sourceObjective = "Schlagt die Invasion Eurer Garnison durch den Schattenrat zurück.\n\n(Sprecht erneut mit Unteroffizier Krähler, um zu beginnen.)", progress = "Wir müssen die Stellung halten!", completion = "Sie sind geschlagen! Ich bin froh, dass wir hier sind, Kommandant. In Draenor. Dämonen zu bekämpfen erinnert mich daran, warum wir auf der Seite der Allianz stehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[36831] = { id = 36831, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattenratinvasion!", description = "Ein kaltes Feuer brennt in meinen Adern, Kommandant. So, als ob ein Hexer mein Herz in seinem grausamen Griff halten würde. Soll sich der Schattenrat doch zeigen!", sourceObjective = "Schlagt die Invasion Eurer Garnison durch den Schattenrat zurück.\n\n(Sprecht erneut mit Unteroffizier Grimmkinn, um zu beginnen.)", completion = "Boah! Wir haben die Dämonen zurückgeschlagen, Kommandant. Mein Blut ist noch immer in Wallung. Meine Augen werden doch nicht etwa rot, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[36832] = { id = 36832, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raus mit dem Xais!", sourceObjective = "Wenn seine Geister nicht bei ihm sind, dann sind die Geister Xais egal. Aber Ihr... Ihr seid zu Xais freundlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[36833] = { id = 36833, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kann ich zu Diensten sein?", sourceObjective = "Ihr habt mich zutiefst beeindruckt, {name}. Wenn Ihr mich mitnehmt, würde ich mich gern Eurer Garnison anschließen.", sourceObjectiveStatus = "unverified-source-field" }
quests[36834] = { id = 36834, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gorgrond Ogre Gateway - Tracking" }
quests[36837] = { id = 36837, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Stompalupagus" }
quests[36838] = { id = 36838, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Euer zweiter Arbeitsauftrag für Alchemie", description = "Erteilt meinem Mann einen weiteren Auftrag. Sobald er fertig ist, könnt Ihr ihn hier abholen.", sourceObjective = "Erteilt einen Arbeitsauftrag und holt ihn nach Abschluss ab.\n\nIhr könnt den Fortschritt über das Garnisonsberichtsfenster verfolgen, das über die Schaltfläche auf der Minikarte aufrufbar ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[36839] = { id = 36839, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Euer zweiter Arbeitsauftrag für Verzauberkunst", description = "Erteilt meinem Gehilfen einen weiteren Auftrag. Sobald er fertig ist, könnt Ihr ihn hier abholen.", sourceObjective = "Erteilt einen Arbeitsauftrag und holt ihn nach Abschluss ab.\n\nIhr könnt den Fortschritt über das Garnisonsberichtsfenster verfolgen, das über die Schaltfläche auf der Minikarte aufrufbar ist.", sourceObjectiveStatus = "unverified-source-field" }
